sequelAtmosphere.forEach((text,i)=>readingFrames[1][13+i].unshift(...compactFrame(N(text))));
// Carry explicit promises from earlier episodes into the sequel, rather than infer them from a score.
const originalSummerSceneFrames=summerSceneFrames;
summerSceneFrames=function(run){const frames=originalSummerSceneFrames(run),d=run.decisions||{};let extra=[];
if(run.step===16&&d[10]===1)extra=[N('Он стоит именно у того фонаря, о котором вы договорились вчера. Ты узнаёшь место раньше, чем его лицо, и впервые за вечер чувствуешь, что хотя бы одно обещание выполнено.')];
if(run.step===16&&d[10]===0)extra=[S('Я здесь, но могу уйти, если тебе лучше одной.'),N('Он помнит, что ты не обещала ему доверия. Ты сама делаешь шаг в его сторону.')];
if(run.step===27&&d[4]===0)extra=[H('Поэтому на рынке ты сначала спросил?'),S('Да. И поэтому снимок остался только у тебя.'),N('Ты вспоминаешь фотографию в телефоне. Теперь в ней есть ещё одна важная деталь, которой не видно в кадре: возможность отказаться.')];
if(run.step===27&&d[4]===1)extra=[H('Ты на рынке даже не стал меня уговаривать.'),S('Отказ — тоже ответ. Мне потребовалось время, чтобы перестать слышать в нём приглашение спорить.')];
if(run.step===30&&d[6]===0)extra=[N('За первым ужином ты призналась ему, что хочешь увидеть своё имя на обложке. Сегодня впервые позволяешь услышать то, что будет под этой обложкой.')];
return [...extra.flatMap(compactFrame),...frames];};

